<?php
namespace App\Models\FbMarketing;
use Illuminate\Database\Eloquent\Model;
class FbmAdSet extends Model{protected $table='fbm_ad_sets';protected $guarded=[];protected $casts=['is_available'=>'boolean','last_seen_at'=>'datetime','provider_created_time'=>'datetime','provider_updated_time'=>'datetime'];protected $hidden=['provider_sync_key'];public function connection(){return $this->belongsTo(FbmConnection::class,'fbm_connection_id');}public function adAccount(){return $this->belongsTo(FbmAdAccount::class,'fbm_ad_account_id');}public function campaign(){return $this->belongsTo(FbmCampaign::class,'fbm_campaign_id');}public function toSafeSummary():array{return ['id'=>(int)$this->id,'fbm_connection_id'=>(int)$this->fbm_connection_id,'fbm_ad_account_id'=>(int)$this->fbm_ad_account_id,'fbm_campaign_id'=>$this->fbm_campaign_id?(int)$this->fbm_campaign_id:null,'connection_name'=>optional($this->connection)->connection_name,'ad_account_name'=>optional($this->adAccount)->asset_name,'campaign_name'=>optional($this->campaign)->name,'name'=>$this->name,'configured_status'=>$this->configured_status,'effective_status'=>$this->effective_status,'optimization_goal'=>$this->optimization_goal,'billing_event'=>$this->billing_event,'daily_budget'=>$this->daily_budget,'lifetime_budget'=>$this->lifetime_budget,'is_available'=>(bool)$this->is_available,'last_seen_at'=>optional($this->last_seen_at)->toDateTimeString()];}}
